  .hero::after { inset: 0 0 auto; aspect-ratio: 3 / 2; background: linear-gradient(to top, var(--band) 0%, transparent 45%); }
  .hero .copy { margin-top: -40px; padding-top: 0; padding-bottom: 48px; }
