button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.toolbar { display: flex; flex-wrap: wrap; gap: 12px 32px; align-items: center; }
.seg-group { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; }
.seg { display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px; border: 1px solid var(--edge); border-radius: 9999px; }
