// One stop's working view, shared by stop.html (shell.js) and teaser.html (teaser.js): the stage element over the museum
// photo, the ghost body, one subsystem per component with its panel cards and talking points, and the frame loop. The page
// chooses what is shown (the Component/View switches on a stop page, the scroll position on the teaser) and calls show().
import { createPanel } from "./panel.js";
import { h, link } from "./dom.js";
import { t } from "./i18n.js";

// The stage element alone, so a page can lay itself out before three.js loads. It keeps the photo's aspect.
export function stageElement(car) {
  const photo = car.photo;
  return h("div", { class: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null },
    photo ? h("img", { src: `stops/${car.slug}/${photo.src}`, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null,
    h("div", { class: "hint" }, t("drag to orbit · pinch to zoom")),
    photo ? h("div", { class: "credit", hidden: true }, t("Photo:"), " ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null);
}

// The car's caveats and sources as two collapsed lists (empty ones left out).
export const caveats = car => [
  car.unverified?.length ? h("details", {}, h("summary", {}, t("Illustrative, not verified")), h("ul", {}, car.unverified.map(u => h("li", {}, u)))) : null,
  car.sources?.length ? h("details", {}, h("summary", {}, t("Sources")), h("ul", {}, car.sources.map(s => h("li", {}, link(s.url, s.label))))) : null,
];

// Loads three.js and the car's subsystems into stageEl (from stageElement). cardsFor(comp) is the element that takes that
// component's panel cards. show({ comp, view: "model" | "photo", outline }, resetOrbit) sets what the stage shows; call it
// before start(). stop() pauses the loop. stage is exposed for ?debug (stats, renderer).
export async function mountViewer(car, stageEl, cardsFor) {
  const [{ createStage }, { buildGhost }] = await Promise.all([import("../scene/stage.js"), import("../scene/ghost-body.js")]);
  const img = stageEl.querySelector("img"), credit = stageEl.querySelector(".credit"), hint = stageEl.querySelector(".hint");
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const stage = createStage(stageEl, car);
  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });

  const instances = new Map();
  for (const comp of car.components) {
    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
    const panel = createPanel(cardsFor(comp), comp.id, `${car.slug}-${comp.id}`);
    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
    panel([{ label: t("Technical facts about the car"), items: [{ list: comp.talk }] }]);
    instances.set(comp.id, inst);
  }

  let shown = null;
  function show(state, resetOrbit = true) {
    shown = { ...state };
    const onPhoto = shown.view === "photo", comp = car.components.find(c => c.id === shown.comp);
    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
    hint.hidden = onPhoto;
    ghost.group.visible = onPhoto ? shown.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
    for (const [id, inst] of instances) inst.layout?.({ active: id === shown.comp, onPhoto });
    stage.setPhotoView(onPhoto);
    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
  }
  return {
    show, stage,
    get state() { return shown; },
    stop: stage.stop,
    start() {
      stage.start(dt => {
        carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
        instances.get(shown.comp).update(dt, { onPhoto: shown.view === "photo" });
      });
    },
  };
}

content.text:
1	// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js, loads
2	// each component's subsystem, and owns the Component/View switches, photo view, car outline, ghost body and frame loop.
3	// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
4	import tour, { teaser } from "../../stops/tour.js";
5	import { registerOffline } from "./offline.js";
6	import { t, loadCar, localizePage, missing } from "./i18n.js";
7	import { h, link } from "./dom.js";
8	import { stageElement, mountViewer, caveats } from "./viewer.js";
9	
10	const params = new URLSearchParams(location.search);
11	const slug = params.get("s");
12	const teaserStops = tour.filter(s => teaser.includes(s.slug));
13	const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
14	const route = inTeaser ? teaserStops : tour;
15	const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
16	const app = document.getElementById("app");
17	
18	const seg = (key, label, items, cur) => h("div", { class: "seg-group", "data-key": key }, h("span", { class: "seg-label" }, label),
19	  h("span", { class: "seg", role: "group", "aria-label": label }, items.map(([v, text]) => h("button", { type: "button", "data-v": v, "aria-pressed": String(v === cur) }, text))));
20	
21	localizePage();
22	registerOffline();
23	if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
24	if (idx < 0) {
25	  document.title = t("Stop not found · Museum tour");
26	  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
27	} else {
28	  main().catch(err => {
29	    console.error(err);
30	    const stage = document.getElementById("stage");
31	    (stage ?? app).append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
32	  });
33	}
34	
35	async function main() {
36	  const stop = route[idx];
37	  const car = await loadCar(stop.slug);
38	  document.title = t("{0} · Museum tour", car.name);
39	  const state = { comp: car.components[0].id, view: "model", outline: false };
40	
41	  // ---------- page ----------
42	  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
43	  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
44	  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
45	  const photo = car.photo;
46	  const stageEl = stageElement(car); stageEl.id = "stage";
47	  const side = h("div", { class: "side" });
48	  const outlineBtn = h("button", { type: "button", class: "outline", "aria-pressed": "false", "data-only": "photo" }, t("Car outline"));
49	  const toolbar = h("div", { class: "toolbar" },
50	    car.components.length > 1 ? seg("comp", t("Component"), car.components.map(c => [c.id, c.label]), state.comp) : null,
51	    photo ? seg("view", t("View"), [["model", t("3D model")], ["photo", t("Museum photo")]], state.view) : null,
52	    photo ? outlineBtn : null);
53	  document.getElementById("where").textContent = t("Stop {0} of {1} · {2} · Level {3}", idx + 1, route.length, t(stop.room), stop.level);
54	  app.replaceChildren(
55	    h("header", {}, h("div", { class: "eyebrow" }, car.eyebrow), h("h1", {}, car.title), h("p", { class: "lede" }, car.lede)),
56	    toolbar,
57	    h("section", { class: "viewer", "aria-label": t("Interactive component viewer") }, stageEl, side),
58	    h("nav", { class: "pager", "aria-label": t("Previous and next stop") },
59	      prev ? link(here(prev), `← ${prevName}`) : h("span"), next ? link(here(next), `${nextName} →`) : h("span")),
60	    h("footer", {}, ...caveats(car),
61	      h("p", { class: "note" }, t("Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints."))));
62	
63	  // ---------- 3D ----------
64	  const viewer = await mountViewer(car, stageEl, () => side);
65	  if (car.note) side.append(h("p", { class: "note" }, car.note));
66	
67	  // The switches show one component's cards, and the cards (or widgets) marked for the current view only.
68	  function layout(resetOrbit = true) {
69	    const onPhoto = state.view === "photo";
70	    document.querySelectorAll("[data-comp]").forEach(el => (el.hidden = el.dataset.comp !== state.comp));
71	    document.querySelectorAll("[data-only]").forEach(el => { if (!el.closest("[data-comp]")?.hidden) el.hidden = (el.dataset.only === "photo") !== onPhoto; });
72	    outlineBtn.setAttribute("aria-pressed", String(state.outline));
73	    viewer.show(state, resetOrbit);
74	  }
75	  toolbar.addEventListener("click", e => {
76	    const b = e.target.closest("button"); if (!b) return;
77	    if (b === outlineBtn) { state.outline = !state.outline; return layout(false); }
78	    const group = b.closest(".seg-group"), key = group.dataset.key;
79	    state[key] = b.dataset.v;
80	    group.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", String(x === b)));
81	    layout();
82	  });
83	
