1	// Teaser page (teaser.html): the teaser stops as scroll stories. Scrolled to, a car's stage (museum photo / 3-D model)
2	// pins, above the steps on a phone held upright and beside them otherwise, and only the steps move on: the introduction
3	// over the museum photo, one step per component with its cards (controls, legend, technical facts) in 3D, then background
4	// back on the photo with the car outline. The step at the reading line sets what the stage shows; only stages on screen
5	// run their frame loop. Each story links its stop page with &r=teaser, so the stop pages page between these stops.
6	import tour, { teaser } from "../../stops/tour.js";
7	import { showOfflineStatus } from "./offline.js";
8	import { t, loadCar, localizePage, missing } from "./i18n.js";
9	import { h } from "./dom.js";
10	import { stageElement, mountViewer, caveats } from "./viewer.js";
11	
12	localizePage();
13	showOfflineStatus(document.getElementById("status"));
14	const cars = await Promise.all(tour.filter(s => teaser.includes(s.slug)).map(s => loadCar(s.slug)));
15	const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
16	document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each car's page links its photo's source.", credits.join(", "));
17	
18	// A step is its content and what the stage shows while it is at the reading line.
19	const step = (state, ...kids) => ({ state, el: h("section", { class: "step" }, kids) });
20	const stories = cars.map(car => {
21	  const first = car.components[0].id;
22	  const comps = car.components.map(c => step({ comp: c.id, view: "model", outline: false }, h("h3", {}, c.label)));
23	  const steps = [
24	    step({ comp: first, view: "photo", outline: false }, h("div", { class: "eyebrow" }, car.eyebrow), h("h2", {}, car.title), h("p", { class: "lede" }, car.lede)),
25	    ...comps,
26	    step({ comp: first, view: "photo", outline: true }, h("footer", {}, h("h3", {}, t("Background")),
27	      h("p", {}, t("Back on the museum photo: the mechanism where it sits, inside the car's outline.")),
28	      car.note ? h("p", {}, car.note) : null, ...caveats(car),
29	      h("a", { class: "pill primary", href: `stop.html?s=${car.slug}&r=teaser` }, t("Open this car on its own page")))),
30	  ];
31	  steps[0].el.classList.add("on");
32	  const stageEl = stageElement(car);
33	  const el = h("article", { class: "story", "aria-label": car.name }, h("div", { class: "story-stage" }, stageEl), h("div", { class: "steps" }, steps.map(s => s.el)));
34	  return { car, el, stageEl, steps, comps, at: 0, viewer: null };
35	});
36	document.getElementById("cars").replaceChildren(...stories.map(s => s.el));
37	
38	await Promise.all(stories.map(async s => {
39	  try {
40	    s.viewer = await mountViewer(s.car, s.stageEl, comp => s.comps[s.car.components.indexOf(comp)].el);
41	    s.viewer.show(s.steps[0].state);
42	  } catch (err) {
43	    console.error(err);
44	    s.stageEl.append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
45	  }
46	}));
47	
48	// The reading line: halfway down the screen beside the pinned stage, or halfway down the part it leaves free below it.
49	// The last step whose top has passed the line is the one shown.
50	function pick() {
51	  for (const s of stories) {
52	    const pane = s.stageEl.parentElement.getBoundingClientRect(), beside = s.steps[0].el.getBoundingClientRect().left >= pane.right;
53	    const line = beside ? innerHeight / 2 : (pane.bottom + innerHeight) / 2;
54	    let at = 0;
55	    s.steps.forEach((st, i) => { if (st.el.getBoundingClientRect().top < line) at = i; });
56	    if (at === s.at) continue;
57	    const before = s.steps[s.at].state;
58	    s.at = at;
59	    s.steps.forEach((st, i) => st.el.classList.toggle("on", i === at));
60	    if (s.viewer && s.steps[at].state !== before) s.viewer.show(s.steps[at].state);
61	  }
62	}
63	let queued = false;
64	const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; pick(); }); } };
65	addEventListener("scroll", schedule, { passive: true });
66	addEventListener("resize", schedule);
67	pick();
68	
69	// Only stages on screen animate: three scenes at once, one of them a live wind tunnel, would be too much for a phone.
70	const onScreen = new IntersectionObserver(entries => {
71	  for (const e of entries) { const v = stories.find(s => s.stageEl === e.target).viewer; if (e.isIntersecting) v.start(); else v.stop(); }
72	});
73	for (const s of stories) if (s.viewer) onScreen.observe(s.stageEl);
74	
75	if (new URLSearchParams(location.search).has("debug")) {
76	  window.__tour = {
77	    stories: stories.map(s => ({ slug: s.car.slug, step: () => s.at, state: () => s.viewer?.state, frames: () => s.viewer?.stage.stats.frames ?? 0 })),
78	    missing: () => [...missing], ready: true,
79	  };
80	}
