1	// One stop's working view, shared by stop.html (shell.js) and teaser.html (teaser.js): the stage element over the museum
2	// photo, the ghost body, one subsystem per component with its panel cards and talking points, and the frame loop. The page
3	// chooses what is shown (the Component/View switches on a stop page, the scroll position on the teaser) and calls show().
4	import { createPanel } from "./panel.js";
5	import { h, link } from "./dom.js";
6	import { t } from "./i18n.js";
7	
8	// The stage element alone, so a page can lay itself out before three.js loads. It keeps the photo's aspect.
9	export function stageElement(car) {
10	  const photo = car.photo;
11	  return h("div", { class: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null },
12	    photo ? h("img", { src: `stops/${car.slug}/${photo.src}`, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null,
13	    h("div", { class: "hint" }, t("drag to orbit · pinch to zoom")),
14	    photo ? h("div", { class: "credit", hidden: true }, t("Photo:"), " ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null);
15	}
16	
17	// The car's caveats and sources as two collapsed lists (empty ones left out).
18	export const caveats = car => [
19	  car.unverified?.length ? h("details", {}, h("summary", {}, t("Illustrative, not verified")), h("ul", {}, car.unverified.map(u => h("li", {}, u)))) : null,
20	  car.sources?.length ? h("details", {}, h("summary", {}, t("Sources")), h("ul", {}, car.sources.map(s => h("li", {}, link(s.url, s.label))))) : null,
21	];
22	
23	// Loads three.js and the car's subsystems into stageEl (from stageElement). cardsFor(comp) is the element that takes that
24	// component's panel cards. show({ comp, view: "model" | "photo", outline }, resetOrbit) sets what the stage shows; call it
25	// before start(). stop() pauses the loop. stage is exposed for ?debug (stats, renderer).
26	export async function mountViewer(car, stageEl, cardsFor) {
27	  const [{ createStage }, { buildGhost }] = await Promise.all([import("../scene/stage.js"), import("../scene/ghost-body.js")]);
28	  const img = stageEl.querySelector("img"), credit = stageEl.querySelector(".credit"), hint = stageEl.querySelector(".hint");
29	  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
30	  const stage = createStage(stageEl, car);
31	  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
32	  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
33	  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });
34	
35	  const instances = new Map();
36	  for (const comp of car.components) {
37	    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
38	    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
39	    const panel = createPanel(cardsFor(comp), comp.id, `${car.slug}-${comp.id}`);
40	    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
41	    panel([{ label: t("Technical facts about the car"), items: [{ list: comp.talk }] }]);
42	    instances.set(comp.id, inst);
43	  }
44	
45	  let shown = null;
46	  function show(state, resetOrbit = true) {
47	    shown = { ...state };
48	    const onPhoto = shown.view === "photo", comp = car.components.find(c => c.id === shown.comp);
49	    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
50	    hint.hidden = onPhoto;
51	    ghost.group.visible = onPhoto ? shown.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
52	    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
53	    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
54	    for (const [id, inst] of instances) inst.layout?.({ active: id === shown.comp, onPhoto });
55	    stage.setPhotoView(onPhoto);
56	    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
57	  }
58	  return {
59	    show, stage,
60	    get state() { return shown; },
61	    stop: stage.stop,
62	    start() {
63	      stage.start(dt => {
64	        carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
65	        instances.get(shown.comp).update(dt, { onPhoto: shown.view === "photo" });
66	      });
67	    },
68	  };
69	}
