33	  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });
34	
35	  const instances = new Map();
36	  for (const comp of car.components) {
37	    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
38	    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
39	    const panel = createPanel(cardsFor(comp), comp.id, `${car.slug}-${comp.id}`);
40	    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
41	    panel([{ label: t("Technical facts about the car"), items: [{ list: comp.talk }] }]);
42	    instances.set(comp.id, inst);
43	  }
44	
45	  let shown = null;
46	  function show(state, resetOrbit = true) {
47	    shown = { ...state };
48	    const onPhoto = shown.view === "photo", comp = car.components.find(c => c.id === shown.comp);
49	    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
50	    hint.hidden = onPhoto;
51	    ghost.group.visible = onPhoto ? shown.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
52	    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
53	    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
54	    for (const [id, inst] of instances) inst.layout?.({ active: id === shown.comp, onPhoto });
55	    stage.setPhotoView(onPhoto);
56	    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
57	  }
58	  return {
59	    show, stage,
60	    get state() { return shown; },
61	    stop: stage.stop,
62	    start() {
63	      stage.start(dt => {
64	        carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
65	        instances.get(shown.comp).update(dt, { onPhoto: shown.view === "photo" });
66	      });
67	    },
68	  };
69	}
70

