content.content:
/* Viewer: stage keeps the museum photo's aspect so the overlay lines up; in phone landscape its height is capped to the
   viewport (width follows) so the page can still be scrolled past the touch-locked stage. */
.viewer { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 24px; align-items: start; }
@media (max-width: 860px) { .viewer { grid-template-columns: minmax(0, 1fr); } }
.stage {
  --ar: 1.4944; position: relative; background: var(--stage); border-radius: var(--radius);
  aspect-ratio: var(--aspect, 1200 / 803); width: min(100%, calc((100svh - 32px) * var(--ar))); justify-self: center;
  overflow: hidden; touch-action: none; -webkit-user-select: none; user-select: none;
}
.stage img, .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.stage img { filter: brightness(.72) saturate(.85); }
.stage .hint { position: absolute; left: 14px; bottom: 10px; font-size: 12px; color: var(--muted); pointer-events: none; }
.stage .credit { position: absolute; right: 10px; bottom: 8px; font-size: 10px; color: #f1f3f5; background: rgba(0,0,0,.55); padding: 2px 8px; border-radius: 9999px; }
.stage .credit a { color: inherit; }
.stage .fail { position: absolute; inset: 0; margin: 0; padding: 16px; }
.side { display: grid; gap: 16px; align-content: start; min-width: 0; }
.panel { background: var(--panel); border-radius: var(--radius); padding: 20px; display: grid; gap: 12px; min-width: 0; }
.readouts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px 8px; }
.readouts div { display: grid; gap: 1px; }
.story-stage { position: sticky; top: 0; z-index: 1; background: var(--bg); padding: max(12px, env(safe-area-inset-top)) 0 12px; }
.story .stage { width: min(100%, calc(45svh * var(--ar))); margin-inline: auto; }
.step { min-height: 60svh; padding: 32px 0; display: grid; gap: 16px; align-content: start; transition: opacity .3s; }
.step:not(.on) { opacity: .4; }
.step h2 { font-size: clamp(36px, 4.4vw, 48px); margin: 0; }
.step h3 { font-family: var(--display); font-weight: 400; font-size: 32px; line-height: 1.15; letter-spacing: 0; margin: 0; color: var(--fg); }
.step footer .pill { justify-self: start; margin-top: 8px; }
@media (orientation: landscape) and (min-width: 600px) {
  .story { display: grid; grid-template-columns: minmax(0, 1fr) clamp(280px, 32vw, 400px); gap: 32px; align-items: start; }
  .story-stage { height: 100svh; display: grid; place-items: center; padding: 16px 0; background: none; }
  .story .stage { width: min(100%, calc((100svh - 32px) * var(--ar))); }
  .step { min-height: 70svh; }
}
@media (prefers-reduced-motion: reduce) { .step { transition: none; } }

