1	// Screenshot of a stop's 3D stage after it has run a while, with the frame rate and any page errors: for checking a
2	// mechanism by eye. Needs the dev server (npm run serve). Uses Playwright's Chromium.
3	// Usage: node tools/stop-shot.mjs <slug> <component id> <out.png> [ms to run, default 15000] [button text …] [--photo]
4	// Scrolls the story to the component's step (--photo: to the closing step, museum photo with the car outline). Buttons are
5	// clicked inside the component's cards, e.g. "Pressure"; the full-page shot goes to <out>-page.png.
6	import { chromium } from "@playwright/test";
7	
8	const args = process.argv.slice(2), photo = args.includes("--photo"), [slug, comp, out, ms = "15000", ...buttons] = args.filter(a => a !== "--photo");
9	const browser = await chromium.launch(), page = await browser.newPage({ viewport: { width: 1280, height: 900 } }), errors = [];
10	page.on("pageerror", e => errors.push(e.message)); page.on("console", m => m.type() === "error" && errors.push(m.text()));
11	await page.goto(`http://localhost:8765/stop.html?s=${slug}&debug`);
12	await page.waitForFunction(() => window.__tour?.ready);
13	const step = photo ? page.locator(".step").last() : page.locator(".step", { has: page.locator(`[data-comp="${comp}"]`) }).first();
14	await step.evaluate(s => s.scrollIntoView({ block: "center" }));
15	for (const b of buttons) await page.click(`[data-comp="${comp}"] button:text-is("${b}")`);
16	const frames = () => page.evaluate(() => window.__tour.stories[0].frames());
17	const f0 = await frames(), t0 = Date.now();
18	await page.waitForTimeout(+ms);
19	const fps = ((await frames()) - f0) / (Date.now() - t0) * 1000;
20	await (await page.$(".stage")).screenshot({ path: out });
21	await page.screenshot({ path: out.replace(/\.png$/, "-page.png") });
22	await browser.close();
23	console.log(`${out}: ${fps.toFixed(0)} fps, errors ${JSON.stringify(errors)}`);

input.content:
// Shared by the e2e specs.
export function watchErrors(page) {
  const errors = [];
  page.on("pageerror", e => errors.push(`pageerror: ${e.message}`));
  page.on("console", m => { if (m.type() === "error") errors.push(`console: ${m.text()}`); });
  return errors;
}

// What each step of a car's story (lib/app/story.js) puts on the stage: intro on the photo, one step per component in 3D,
// background on the photo with the car outline.
export const stepsOf = car => {
  const first = car.components[0].id;
  return [{ comp: first, view: "photo", outline: false }, ...car.components.map(c => ({ comp: c.id, view: "model", outline: false })), { comp: first, view: "photo", outline: true }];
};

// The page's ?debug handle for story i: the step at the reading line and what the stage shows.
export const shown = (page, i = 0) => page.evaluate(i => ({ step: window.__tour.stories[i].step(), state: window.__tour.stories[i].state() }), i);

