    const steps = [{ comp: first, view: "photo", outline: false }, ...car.components.map(c => ({ comp: c.id, view: "model", outline: false })), { comp: first, view: "photo", outline: true }];
''','''    const el = page.locator(".story").nth(i), steps = stepsOf(car);
'''),
('''      await expect.poll(() => shown(i)).toEqual({ step: k, state: want });''','''      await expect.poll(() => shown(page, i)).toEqual({ step: k, state: want });'''),
]
for a,b in rep:
    assert a in s, a[:70]
