115	const rot = ([x, y], a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];
116	
117	// Double-pivot (stub-axle) steering with a trapezoid linkage: kingpins at (0, ±k), steering arms of length a pointing
118	// rearwards and inwards by β, joined by one tie rod. β = atan(k / wheelbase) aims both arms at the rear-axle centre,
119	// the classic condition for the wheel axes to meet near one point (Ackermann).
120	export function createDoublePivot({ kingpinHalf: k, arm: a, wheelbase: wb, armAngle }) {
121	  const beta = armAngle ?? Math.atan(k / wb);
122	  const KL = [0, k], KR = [0, -k];
123	  const armVec = (side, d) => rot([-a * Math.cos(beta), -side * a * Math.sin(beta)], d);
124	  const end = (K, side, d) => { const v = armVec(side, d); return [K[0] + v[0], K[1] + v[1]]; };
125	  const tie = hyp(...[0, 1].map(i => end(KL, 1, 0)[i] - end(KR, -1, 0)[i]));
126	
127	  // Given the left wheel's angle (driven by the steering column), close the tie rod for the right wheel.
128	  function solve(dL) {
129	    const PL = end(KL, 1, dL);
130	    const dx = PL[0] - KR[0], dy = PL[1] - KR[1], d = hyp(dx, dy);
131	    const along = (a * a - tie * tie + d * d) / (2 * d), h = Math.sqrt(Math.max(0, a * a - along * along));
132	    const mx = KR[0] + along * dx / d, my = KR[1] + along * dy / d;
133	    const cands = [[mx + h * dy / d, my - h * dx / d], [mx - h * dy / d, my + h * dx / d]];
134	    const guess = end(KR, -1, dL);
135	    const PR = cands.reduce((best, c) => (hyp(c[0] - guess[0], c[1] - guess[1]) < hyp(best[0] - guess[0], best[1] - guess[1]) ? c : best));
136	    const v0 = armVec(-1, 0), v = [PR[0] - KR[0], PR[1] - KR[1]];
137	    const raw = Math.atan2(v[1], v[0]) - Math.atan2(v0[1], v0[0]);
138	    const dR = Math.atan2(Math.sin(raw), Math.cos(raw));   // wrap to (−π, π]
139	    return { dL, dR, PL, PR, KL, KR, ...turning(dL, dR) };
140	  }
141	
142	  // Each front wheel's axis meets the rear-axle line at y = ±k + wb / tan δ. Equal y's = no tyre scrub.
143	  function turning(dL, dR) {
144	    if (Math.abs(dL) < 1e-6 || Math.abs(dR) < 1e-6) return { icrL: Infinity, icrR: Infinity, radius: Infinity, idealOuter: 0 };
145	    const icrL = k + wb / Math.tan(dL), icrR = -k + wb / Math.tan(dR);
146	    const inner = Math.max(Math.abs(dL), Math.abs(dR));
147	    const idealOuter = Math.sign(dL) * Math.atan(1 / (1 / Math.tan(inner) + 2 * k / wb));
148	    const icrY = (icrL + icrR) / 2, outerK = dL > 0 ? KR : KL;
149	    return { icrL, icrR, idealOuter, radius: hyp(-wb - outerK[0], icrY - outerK[1]) };
150	  }
151	
152	  return { k, a, wb, beta, tie, solve, armVec };
153	}
154	
155	// The older centre-pivot (turntable) axle: the whole beam swings about its middle. The wheel axes always meet,
156	// but the front support narrows (k·cos δ) and the inner wheel swings back by k·sin δ, toward the body.
157	export function centrePivot({ kingpinHalf: k, wheelbase: wb }, d) {
158	  const L = rot([0, k], d), R = rot([0, -k], d);
159	  const straight = Math.abs(d) < 1e-6;
160	  const icrY = straight ? Infinity : wb / Math.tan(d), outer = d > 0 ? R : L;
161	  return { L, R, halfTrack: k * Math.cos(d), swingBack: k * Math.abs(Math.sin(d)), icrY, radius: straight ? Infinity : hyp(outer[0] + wb, outer[1] - icrY) };
162	}
163	
