1	// Self-levelling air suspension against steel springs. Load the car: on steel springs the body sinks, mostly at the
2	// rear, and stays down. On air springs it sinks too, then the levelling valves let more air into the bellows until the
3	// body is back at ride height; the higher pressure also stiffens the spring, so the ride frequency hardly changes.
4	// Params (mm, ground at z = 0): label, front (x of the front axle), wheelbase, halfTrack, wheelR,
5	// corners { front: { mass, extra }, rear: { mass, extra } } (kg sprung per corner; kg added per corner when loaded),
6	// air { area (m²), volume (m³), n }, steel { front, rear } (N/m), damping (N·s/m), bellows { r, h, z0 } (mm),
7	// load { heads: [[x, y, z]], boot: [x, z] } (mm, what is drawn when loaded).
8	import * as THREE from "three";
9	import { V, mat, ball, tyre, helix } from "../lib/scene/helpers.js";
10	import { createCorner } from "../lib/model/air-spring.js";
11	
12	const PATM = 101325, SUB = 10;
13	
14	export function create(ctx, p) {
15	  const { stage, carRoot, t } = ctx, m = v => v / 1000;
16	  const world = new THREE.Group(); stage.scene.add(world);   // wheels and axles do not move with the body
17	  const xF = m(p.front), wb = m(p.wheelbase), yT = m(p.halfTrack), R = m(p.wheelR), bz0 = m(p.bellows.z0), bh = m(p.bellows.h), br = m(p.bellows.r);
18	  const tyreMat = mat(0x2a2d31, { roughness: 0.9 }), rimMat = mat(0x9aa4ad, { metalness: 0.5 }), airMat = stage.tokenMat("--l4"), coilMat = stage.tokenMat("--metal");
19	  tyreMat.transparent = rimMat.transparent = true;   // faded over the museum photo
20	  const axles = [["front", xF], ["rear", xF - wb]];
21	  const corners = axles.flatMap(([axle, x]) => [1, -1].map(s => {
22	    const wheel = tyre(tyreMat, R - 0.07, 0.07); wheel.position.set(x, s * yT, R); world.add(wheel);
23	    const rim = new THREE.Mesh(new THREE.CylinderGeometry(R - 0.12, R - 0.12, 0.16, 28), rimMat); rim.position.set(x, s * yT, R); world.add(rim);
24	    const y = s * (yT - 0.2);
25	    const bellows = new THREE.Group(); bellows.position.set(x, y, bz0); world.add(bellows);   // three rolls, spread over the height each frame
26	    const rolls = [0, 1, 2].map(() => { const t = new THREE.Mesh(new THREE.TorusGeometry(br * 0.78, br * 0.22, 10, 28), airMat); bellows.add(t); return t; });
27	    const coil = new THREE.Mesh(helix(V(0, 0, 0), V(0, 0, 1), 6, br * 0.85, 0.012), coilMat); coil.position.set(x, y, bz0); world.add(coil);
28	    return { axle, bellows, rolls, coil };
29	  }));
30	  const loadGroup = new THREE.Group(); carRoot.add(loadGroup);
31	  const loadMat = stage.tokenMat("--accent");
32	  for (const hd of p.load.heads) loadGroup.add(ball(loadMat, 0.1, V(m(hd[0]), m(hd[1]), m(hd[2]))));
33	  const boot = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.8, 0.3), stage.tokenMat("--l2")); boot.position.set(m(p.load.boot[0]), 0, m(p.load.boot[1])); loadGroup.add(boot);
34	
35	  // Four corner models: front/rear × air/steel; both systems run all the time so switching shows each one's state.
36	  const make = (kind, axle) => createCorner({ kind, air: p.air, k: p.steel[axle], emptyMass: p.corners[axle].mass, damping: p.damping });
37	  const sims = { air: { front: make("air", "front"), rear: make("air", "rear") }, steel: { front: make("steel", "front"), rear: make("steel", "rear") } };
38	  let mode = "air", loaded = false, auto = !ctx.reducedMotion, clock = 0;
39	  const ui = ctx.panel([{ label: p.label, badge: { id: "valve", text: "" }, items: [
40	    { buttons: [{ id: "air", label: t("Air suspension, self-levelling"), pressed: true, onClick: () => setMode("air") }, { id: "steel", label: t("Steel springs"), pressed: false, onClick: () => setMode("steel") }] },
41	    { buttons: [{ id: "load", toggle: [t("Loaded: 4 people + luggage"), t("Driver only")], pressed: false, onClick: v => { auto = false; ui.toggle("auto").set(false); loaded = v; } }] },
42	    { readouts: [{ id: "front", label: t("Front sits lower by"), unit: t("mm") }, { id: "rear", label: t("Rear sits lower by"), unit: t("mm") },
43	      { id: "bar", label: t("Rear bellows pressure"), unit: t("bar") }, { id: "hz", label: t("Rear ride frequency"), unit: t("Hz (bounce rate)") }, { id: "pitch", label: t("Nose up"), unit: t("deg") }] },
44	    { buttons: [{ id: "auto", toggle: [t("Auto demo on"), t("Auto demo off")], pressed: auto, onClick: v => (auto = v) }] },
45	    { key: [["--l4", t("air bellows")], ["--metal", t("steel coil spring")], ["--accent", t("passengers")], ["--l2", t("luggage")]] },
46	  ] }]);
47	  function setMode(md) { mode = md; ui.toggle("air").set(md === "air"); ui.toggle("steel").set(md === "steel"); }
48	
49	  const massOf = axle => p.corners[axle].mass + (loaded ? p.corners[axle].extra : 0);
50	  function rideHz(axle) {
51	    const c = sims[mode][axle], mass = massOf(axle);
52	    const k = mode === "air" ? p.air.n * (c.pressure() + PATM) * p.air.area ** 2 / (p.air.volume - p.air.area * c.z) : p.steel[axle];
53	    return Math.sqrt(k / mass) / (2 * Math.PI);
54	  }
55	  return {
56	    layout({ active, onPhoto }) { world.visible = active; loadGroup.visible = active && loaded; tyreMat.opacity = rimMat.opacity = onPhoto ? 0.12 : 1; },
57	    update(dt, { onPhoto }) {
58	      if (auto) { clock += dt; const l = Math.floor(clock / 7) % 2 === 1; if (l !== loaded) { loaded = l; ui.toggle("load").set(l); } }
59	      loadGroup.visible = loaded;
60	      const h = Math.min(dt, 0.05) / SUB;
61	      for (let i = 0; i < SUB; i++) for (const md of ["air", "steel"]) for (const axle of ["front", "rear"]) sims[md][axle].step(massOf(axle), h);
62	      const zF = sims[mode].front.z, zR = sims[mode].rear.z, sin = (zF - zR) / wb;
63	      if (!onPhoto) { carRoot.rotation.y = Math.asin(sin); carRoot.position.z = -zF + xF * sin; }   // the photo's car stays put
64	      for (const c of corners) {
65	        const sag = sims[mode][c.axle].z, k = Math.max(0.2, (bh - sag) / bh);
66	        c.bellows.visible = mode === "air"; c.coil.visible = mode === "steel";
67	        c.rolls.forEach((r, i) => (r.position.z = bh * k * (i + 0.5) / 3)); c.coil.scale.set(1, 1, bh * k);
68	      }
69	      const valve = sims.air.rear.valve === "level" ? sims.air.front.valve : sims.air.rear.valve;
70	      ui.badge("valve").set(mode === "steel" ? t("No levelling") : valve === "filling" ? t("Valves: letting air in") : valve === "venting" ? t("Valves: letting air out") : t("At ride height"), mode === "air" && valve === "level");
71	      ui.set("front", (zF * 1000).toFixed(0)); ui.set("rear", (zR * 1000).toFixed(0));
72	      ui.set("bar", mode === "air" ? (sims.air.rear.pressure() / 1e5).toFixed(2) : "–");
73	      ui.set("hz", rideHz("rear").toFixed(2)); ui.set("pitch", (-Math.asin(sin) * 180 / Math.PI).toFixed(2));
74	    },
75	  };
76	}
77	// Self-levelling air suspension vs a steel spring, one corner. Pure: no DOM, no three.js. SI units.
78	// Air spring: gauge pressure on an effective area carries the load; stiffness k = n·p_abs·A²/V rises with the load,
79	// so the ride frequency stays nearly constant. A steel spring keeps k and sags instead.
80	const PATM = 101325, G = 9.81;
81	const hz = (k, m) => Math.sqrt(k / m) / (2 * Math.PI);
82	
83	// Static values at ride height. a = { area (m²), volume (m³), n (polytropic exponent) }.
84	export function airStatic(a, mass) {
85	  const pg = mass * G / a.area, k = (a.n ?? 1.3) * (pg + PATM) * a.area ** 2 / a.volume;
86	  return { pg, k, f: hz(k, mass) };
87	}
88	export const steelStatic = (k, mass, emptyMass) => ({ sag: (mass - emptyMass) * G / k, f: hz(k, mass) });
89	
90	// Dynamic corner. kind "air": air spring with a levelling valve that adds or vents air while the body is off ride height.
91	// kind "steel": spring of rate k, preloaded to carry emptyMass at ride height. z = sag below ride height (m), + = lower.
92	// The valve is proportional: it moves air at up to valveRate (share of the air per second) once the body is `full` metres
93	// off ride height, and does nothing inside ±tol.
94	export function createCorner({ kind, air, k, emptyMass, damping, valveRate = 0.15, tol = 0.002, full = 0.02 }) {
95	  const n = air?.n ?? 1.3;
96	  const s = { z: 0, v: 0, C: 0, valve: "level" };
97	  if (kind === "air") s.C = (airStatic(air, emptyMass).pg + PATM) * air.volume ** n;   // p·Vⁿ of the air in the spring
98	  s.step = (mass, dt) => {
99	    let F;
100	    if (kind === "air") F = (s.C / (air.volume - air.area * s.z) ** n - PATM) * air.area;
101	    else F = emptyMass * G + k * s.z;
102	    s.v += (mass * G - F - damping * s.v) / mass * dt;
103	    s.z += s.v * dt;
104	    if (kind === "air") {
105	      s.valve = s.z > tol ? "filling" : s.z < -tol ? "venting" : "level";
106	      if (s.valve !== "level") s.C *= 1 + valveRate * Math.max(-1, Math.min(1, s.z / full)) * dt;
107	    }
108	    return s;
109	  };
110	  s.pressure = () => (kind === "air" ? s.C / (air.volume - air.area * s.z) ** n - PATM : NaN);   // gauge, Pa
111	  return s;
112	}
