81	const hz = (k, m) => Math.sqrt(k / m) / (2 * Math.PI);
82	
83	// Static values at ride height. a = { area (m²), volume (m³), n (polytropic exponent) }.
84	export function airStatic(a, mass) {
85	  const pg = mass * G / a.area, k = (a.n ?? 1.3) * (pg + PATM) * a.area ** 2 / a.volume;
86	  return { pg, k, f: hz(k, mass) };
87	}
88	export const steelStatic = (k, mass, emptyMass) => ({ sag: (mass - emptyMass) * G / k, f: hz(k, mass) });
89	
90	// Dynamic corner. kind "air": air spring with a levelling valve that adds or vents air while the body is off ride height.
91	// kind "steel": spring of rate k, preloaded to carry emptyMass at ride height. z = sag below ride height (m), + = lower.
92	// The valve is proportional: it moves air at up to valveRate (share of the air per second) once the body is `full` metres
93	// off ride height, and does nothing inside ±tol.
94	export function createCorner({ kind, air, k, emptyMass, damping, valveRate = 0.15, tol = 0.002, full = 0.02 }) {
95	  const n = air?.n ?? 1.3;
96	  const s = { z: 0, v: 0, C: 0, valve: "level" };
97	  if (kind === "air") s.C = (airStatic(air, emptyMass).pg + PATM) * air.volume ** n;   // p·Vⁿ of the air in the spring
98	  s.step = (mass, dt) => {
99	    let F;
100	    if (kind === "air") F = (s.C / (air.volume - air.area * s.z) ** n - PATM) * air.area;
101	    else F = emptyMass * G + k * s.z;
102	    s.v += (mass * G - F - damping * s.v) / mass * dt;
103	    s.z += s.v * dt;
104	    if (kind === "air") {
105	      s.valve = s.z > tol ? "filling" : s.z < -tol ? "venting" : "level";
106	      if (s.valve !== "level") s.C *= 1 + valveRate * Math.max(-1, Math.min(1, s.z / full)) * dt;
107	    }
108	    return s;
109	  };
110	  s.pressure = () => (kind === "air" ? s.C / (air.volume - air.area * s.z) ** n - PATM : NaN);   // gauge, Pa
111	  return s;
112	}
