84	  });
85	  for (const l of loads) for (let a = 0; a < 3; a++) F[3 * l.node + a] += l.f[a];
86	  // Nodes no member touches carry nothing: hold them so the system stays solvable.
87	  const used = new Set(members.flatMap(m => m.ends));
88	  const held = [...fixed, ...nodes.flatMap((_, i) => (used.has(i) ? [] : [{ node: i, dof: "xyz" }]))];
89	  for (const s of held) for (const c of s.dof) {
