94	  const u = nodes.map((_, i) => [x[3 * i], x[3 * i + 1], x[3 * i + 2]]);
95	  const forces = members.map((m, n) => geo[n].k * dot(geo[n].e, sub(u[m.ends[1]], u[m.ends[0]])));
