106	  const nodes = stations.flatMap(st => [1, -1].flatMap(sy => st.z.map(z => [st.x, sy * st.w, z])));
107	  const members = [], add = (i, j, tag) => members.push({ ends: [i, j], EA, tag });
108	  stations.forEach((_, s) => {
