125	}
126	
127	// Torsion test: rear station held, one front corner lifted by F (N); the other front corner rests on a support.
128	// Returns stiffness (N·m per degree of twist) and the solution for drawing.
129	export function twistTest(frame, front, rear, F) {
130	  const { node } = frame;
131	  const sol = solveTruss({
132	    ...frame,
133	    fixed: [{ node: node(rear, 0, 0), dof: "xyz" }, { node: node(rear, 1, 0), dof: "xz" }, { node: node(front, 1, 0), dof: "z" }],
134	    loads: [{ node: node(front, 0, 0), f: [0, 0, F] }],
135	  });
136	  const track = 2 * frame.nodes[node(front, 0, 0)][1];
137	  const twist = Math.atan2(sol.u[node(front, 0, 0)][2], track) * 180 / Math.PI;
138	  return { ...sol, twist, stiffness: F * track / 1000 / twist };
139	}
