// Tubular space frame under a twisting load: one front wheel is lifted, the rear is held, as when a car crosses a kerb at
// an angle. Tubes are coloured by force (tension, compression) and the bending is drawn hugely exaggerated. Compare the
// 300 SL frame, whose side trusses run deep through the door area (so the doors had to open upwards), with the same frame
// cut down to a low sill for ordinary doors.
// Params (mm, ground at z = 0): label, stations, bays (lib/model/truss.js; door: "high" marks the door bays), EA (N),
// load (N at the front-left corner), exaggerate (× displacement), modes { high, low } (button labels).
import * as THREE from "three";
import { V, rod, place, ball } from "../lib/scene/helpers.js";
import { tubeFrame, twistTest } from "../lib/model/truss.js";

export function create(ctx, p) {
  const { stage, carRoot, t } = ctx;
  const group = new THREE.Group(); carRoot.add(group);
  const tens = stage.tokenMat("--l1"), comp = stage.tokenMat("--l4"), idle = stage.tokenMat("--metal");
  const solve = door => {
    const f = tubeFrame(p.stations, p.bays.map(b => (b.door ? { ...b, door } : b)), p.EA), r = twistTest(f, 0, p.stations.length - 1, p.load);
    const maxF = Math.max(...r.forces.map(Math.abs)), base = f.nodes.map(n => V(n[0] / 1000, n[1] / 1000, n[2] / 1000));
    const tubes = f.members.map((mb, i) => {
      const F = r.forces[i], t = rod(Math.abs(F) < 0.06 * maxF ? idle : F > 0 ? tens : comp, mb.tag.startsWith("door") ? 0.009 : 0.007);
      group.add(t); return { t, ends: mb.ends };
    });
    return { ...r, f, maxF, base, tubes };
  };
  const modes = { high: solve("high"), low: solve("low") };

  // Load arrow at the lifted corner, small balls where the frame is held.
  const nodeOf = (s, side, lv) => s * 6 + side * 3 + lv, last = p.stations.length - 1;
  const lift = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 16), stage.tokenMat("--l2")); lift.rotation.x = Math.PI / 2; group.add(lift);
  const liftRod = rod(stage.tokenMat("--l2"), 0.015); group.add(liftRod);
  const supports = [nodeOf(last, 0, 0), nodeOf(last, 1, 0), nodeOf(0, 1, 0)].map(n => { const b = ball(stage.tokenMat("--muted"), 0.035); group.add(b); return { b, n }; });

  let mode = "high", clock = 0, playing = !ctx.reducedMotion, f = 0.5;
  const ui = ctx.panel([{ label: p.label, items: [
    { buttons: [{ id: "high", label: p.modes.high, pressed: true, onClick: () => setMode("high") }, { id: "low", label: p.modes.low, pressed: false, onClick: () => setMode("low") }] },
    { readouts: [{ id: "load", label: t("Lift at the front wheel"), unit: t("N") }, { id: "twist", label: t("Frame twist"), unit: t("deg") },
      { id: "stiff", label: t("Twist stiffness"), unit: t("N·m per degree") }, { id: "rel", label: t("Compared with the 300 SL frame"), unit: "%" },
      { id: "maxF", label: t("Hardest-working tube"), unit: t("N") }] },
    { buttons: [{ id: "play", toggle: [t("Pause"), t("Play")], pressed: playing, onClick: v => (playing = v) }] },
    { key: [["--l1", t("tube in tension")], ["--l4", t("in compression")], ["--metal", t("hardly loaded")], ["--l2", t("lift")], ["--muted", t("held")]] },
    { text: t("Bending drawn {0}× larger than it is. Tube sizes and frame shape are simplified.", p.exaggerate) },
  ] }]);
  function setMode(md) { mode = md; ui.toggle("high").set(md === "high"); ui.toggle("low").set(md === "low"); }

  const q = V(0, 0, 0), a = V(0, 0, 0), b = V(0, 0, 0);
  const posOf = (s, n, out) => out.copy(s.base[n]).addScaledVector(q.set(...s.u[n]).multiplyScalar(1 / 1000), p.exaggerate * f);
  return {
    layout({ active }) { group.visible = active; },
    update(dt) {
      if (playing) { clock += dt; f = 0.5 - 0.5 * Math.cos(clock * 1.4); }
      for (const [k, s] of Object.entries(modes)) for (const tb of s.tubes) {
        tb.t.visible = k === mode;
        if (k === mode) place(tb.t, posOf(s, tb.ends[0], a), posOf(s, tb.ends[1], b).clone());
      }
      const s = modes[mode], corner = posOf(s, nodeOf(0, 0, 0), a);
      lift.position.copy(corner).add(q.set(0, 0, -0.12)); place(liftRod, corner.clone().add(q.set(0, 0, -0.42)), corner.clone().add(q.set(0, 0, -0.14)));
      for (const sp of supports) posOf(s, sp.n, sp.b.position).add(q.set(0, 0, -0.04));
      ui.set("load", (p.load * f).toFixed(0)); ui.set("twist", (s.twist * f).toFixed(3));
      ui.set("stiff", s.stiffness.toFixed(0)); ui.set("rel", (s.stiffness / modes.high.stiffness * 100).toFixed(0));
      ui.set("maxF", (s.maxF * f).toFixed(0));
    },
  };
}
// Pin-jointed space truss, linear elastic. Pure: no DOM, no three.js. Units: mm, N.
import { gauss } from "./linkage.js";

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

// t = { nodes: [[x, y, z]], members: [{ ends: [i, j], EA }], fixed: [{ node, dof: "xyz" }], loads: [{ node, f: [fx, fy, fz] }] }.
// Returns node displacements u (mm) and member forces (N, + = tension). Supports must remove every rigid-body motion.
export function solveTruss({ nodes, members, fixed, loads }) {
  const N = 3 * nodes.length, K = Array.from({ length: N }, () => new Float64Array(N)), F = new Float64Array(N);
  const geo = members.map(m => {
    const d = sub(nodes[m.ends[1]], nodes[m.ends[0]]), L = Math.hypot(...d);
    return { e: d.map(c => c / L), k: m.EA / L };
  });
  members.forEach((m, n) => {
    const [i, j] = m.ends, { e, k } = geo[n];
    for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) {
      const kab = k * e[a] * e[b];
      K[3 * i + a][3 * i + b] += kab; K[3 * j + a][3 * j + b] += kab;
      K[3 * i + a][3 * j + b] -= kab; K[3 * j + a][3 * i + b] -= kab;
    }
  });
  for (const l of loads) for (let a = 0; a < 3; a++) F[3 * l.node + a] += l.f[a];
  // Nodes no member touches carry nothing: hold them so the system stays solvable.
  const used = new Set(members.flatMap(m => m.ends));
  const held = [...fixed, ...nodes.flatMap((_, i) => (used.has(i) ? [] : [{ node: i, dof: "xyz" }]))];
  for (const s of held) for (const c of s.dof) {
    const r = 3 * s.node + "xyz".indexOf(c);
    K[r].fill(0); for (const row of K) row[r] = 0; K[r][r] = 1; F[r] = 0;
  }
  const x = gauss(K.map(row => Array.from(row)), Array.from(F));
  const u = nodes.map((_, i) => [x[3 * i], x[3 * i + 1], x[3 * i + 2]]);
  const forces = members.map((m, n) => geo[n].k * dot(geo[n].e, sub(u[m.ends[1]], u[m.ends[0]])));
  return { u, forces };
}

// Tubular frame from cross-sections. Each station { x, w (half width), z: [floor, sill, top] } has six nodes (left/right ×
// three levels), braced into a rigid ring. Each bay between stations: longitudinals, a diagonal in every side panel and in
// the floor, and optionally in the top. door: "high" keeps the full-height side truss (300 SL); "low" cuts it down to the
// sill, as a conventional door opening would (no top rail, no upper side diagonal); a station between two such bays
// then has no top ring either. node(s, side, level): side 0 = left (+y), 1 = right (−y); level 0 floor, 1 sill, 2 top.
export function tubeFrame(stations, bays, EA) {
  const node = (s, side, level) => s * 6 + side * 3 + level;
  const nodes = stations.flatMap(st => [1, -1].flatMap(sy => st.z.map(z => [st.x, sy * st.w, z])));
  const members = [], add = (i, j, tag) => members.push({ ends: [i, j], EA, tag });
  stations.forEach((_, s) => {
    const top = [bays[s - 1], bays[s]].some(b => b && b.door !== "low");
    for (let lv = 0; lv < (top ? 3 : 2); lv++) add(node(s, 0, lv), node(s, 1, lv), "ring");
    for (const side of [0, 1]) { add(node(s, side, 0), node(s, side, 1), "ring"); if (top) add(node(s, side, 1), node(s, side, 2), "ring"); }
    add(node(s, 0, 0), node(s, 1, 1), "ring"); if (top) add(node(s, 0, 1), node(s, 1, 2), "ring");
  });
  bays.forEach((b, s) => {
    const low = b.door === "low", tag = b.door ? "door" : "bay";
    for (const side of [0, 1]) {
      for (let lv = 0; lv < 3; lv++) if (!(low && lv === 2)) add(node(s, side, lv), node(s + 1, side, lv), lv === 2 ? `${tag}-top` : tag);
      add(node(s, side, 0), node(s + 1, side, 1), tag);
      if (!low) add(node(s, side, 1), node(s + 1, side, 2), `${tag}-top`);
    }
    add(node(s, 0, 0), node(s + 1, 1, 0), tag);
    if (b.top && !low) add(node(s, 0, 2), node(s + 1, 1, 2), tag);
  });
  return { nodes, members, node };
}

// Torsion test: rear station held, one front corner lifted by F (N); the other front corner rests on a support.
// Returns stiffness (N·m per degree of twist) and the solution for drawing.
export function twistTest(frame, front, rear, F) {
  const { node } = frame;
  const sol = solveTruss({
    ...frame,
    fixed: [{ node: node(rear, 0, 0), dof: "xyz" }, { node: node(rear, 1, 0), dof: "xz" }, { node: node(front, 1, 0), dof: "z" }],
    loads: [{ node: node(front, 0, 0), f: [0, 0, F] }],
  });
  const track = 2 * frame.nodes[node(front, 0, 0)][1];
  const twist = Math.atan2(sol.u[node(front, 0, 0)][2], track) * 180 / Math.PI;
  return { ...sol, twist, stiffness: F * track / 1000 / twist };
}

