1	// Car-transporter deck hoist (Mercedes-Benz 1624): one central hydraulic pump, and at each deck end a cylinder per side
2	// with a pulley block whose cable runs over a pulley at the top of the post down to the deck. Raise both ends to lift
3	// the deck, one end to tilt it. The block gives `falls` times the piston's travel for `falls` times the force.
4	// Params (mm, ground at z = 0): label, hoist (lib/model/hoist.js; stroke m, bore m, flow = the pump's, l/min), deck { rear [x, z],
5	// front [x, z] (ends at their lowest), y (cable half-spacing), mass (kg) }, car { mass (kg), x (centre of mass),
6	// size [length, width, height] }, posts { base (z of the cylinder bases), top (z of the top pulleys) },
7	// presets [{ id, label, front, rear }] (rise of each end, mm).
8	import * as THREE from "three";
9	import { V, rod, place } from "../lib/scene/helpers.js";
10	import { deckRise, strokeFor, deckSpeed, pressureBar, endPulls } from "../lib/model/hoist.js";
11	
12	const SHEAVE = 0.045;   // sheave radius (m)
13	
14	export function create(ctx, p) {
15	  const { stage, carRoot, t } = ctx, m = v => v / 1000, h = p.hoist, D = p.deck;
16	  const group = new THREE.Group(); carRoot.add(group);
17	  const deckMat = stage.tokenMat("--l2", { transparent: true, opacity: 0.55 }), cylMat = stage.tokenMat("--l4", { metalness: 0.4 });
18	  const rodMat = stage.tokenMat("--metal", { metalness: 0.6 }), postMat = stage.tokenMat("--muted");
19	  const cableMat = new THREE.LineBasicMaterial(); stage.bind(cableMat.color, "--l1");
20	  const zBase = m(p.posts.base), zTop = m(p.posts.top), barrel = h.stroke + 0.12;
21	  const ends = { rear: { x: m(D.rear[0]), z0: m(D.rear[1]) }, front: { x: m(D.front[0]), z0: m(D.front[1]) } };
22	
23	  // Deck and the car on it: boxes posed from the two end points each frame.
24	  const L0 = Math.hypot(ends.front.x - ends.rear.x, ends.front.z0 - ends.rear.z0);
25	  const deck = new THREE.Mesh(new THREE.BoxGeometry(1, 2 * m(D.y), 0.05), deckMat); group.add(deck);
