67	    for (const c of units) {
68	      const e = ends[c.name], zDeck = e.z0 + rise[c.name], out = strokeFor(h, rise[c.name]);
69	      const zFixed = zBase - SHEAVE - 0.01, zMoving = zBase + barrel + out + 0.03;
