75	        c.falls.setXYZ(2 * k, c.x + dx, c.y, zFixed); c.falls.setXYZ(2 * k + 1, c.x + dx, c.y, zMoving);
76	      }
77	      const n = 2 * h.falls;
78	      c.falls.setXYZ(n, c.x - SHEAVE, c.y, zFixed); c.falls.setXYZ(n + 1, e.x - SHEAVE, c.y, zTop);
79	      c.falls.setXYZ(n + 2, e.x + SHEAVE * 0.2, c.y, zTop + SHEAVE); c.falls.setXYZ(n + 3, e.x + SHEAVE * 0.2, c.y - c.s * 0.07, zDeck);
80	      c.falls.needsUpdate = true;
81	    }
