95	      ui.set("tilt", ((a * 180) / Math.PI).toFixed(1)); ui.set("stroke", (strokeFor(h, rise.front) * 1000).toFixed(0));
96	      ui.set("pull", (pulls.front / 2000).toFixed(1));
97	      ui.set("pF", pressureBar(h, pulls.front / 2).toFixed(0)); ui.set("pR", pressureBar(h, pulls.rear / 2).toFixed(0));
98	      ui.badge("state").set(moving.length ? (moving.length === 2 ? t("Both ends moving: the flow is shared") : moving[0] === "front" ? t("Moving the front end") : t("Moving the rear end")) : t("Holding · {0} mm of travel", (deckRise(h, h.stroke) * 1000).toFixed(0)), moving.length > 0);
