33	  const sheave = () => new THREE.Mesh(new THREE.CylinderGeometry(SHEAVE, SHEAVE, 0.02, 24), rodMat);
34	  const lines = n => { const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(n * 6), 3)); const l = new THREE.LineSegments(g, cableMat); l.frustumCulled = false; group.add(l); return g.attributes.position; };
35	  const units = [];
36	  for (const [name, e] of Object.entries(ends)) for (const s of [1, -1]) {
37	    const y = s * (m(D.y) + 0.07), cx = e.x;   // the cylinder stands beside its post
38	    group.add(place(rod(postMat, 0.03), V(e.x, y, zBase - 0.05), V(e.x, y, zTop + 0.06)));
39	    const top = sheave(); top.position.set(e.x, y, zTop); group.add(top);   // sheaves turn about y: the cable runs in x-z
40	    const cyl = { name, s, x: cx + 0.09, y, barrel: place(rod(cylMat, 0.035), V(cx + 0.09, y, zBase), V(cx + 0.09, y, zBase + barrel)), rod: rod(rodMat, 0.016) };
