42	    group.add(cyl.fixed, cyl.moving);
43	    group.add(cyl.barrel, cyl.rod); units.push(cyl);
44	  }
45	
46	  // ---------- state + panel ----------
47	  const first = p.presets[0], rise = { rear: m(first.rear), front: m(first.front) }, target = { ...rise };
48	  let loaded = true, demo = !ctx.reducedMotion, step = 0, wait = 0;
49	  const ui = ctx.panel([{ label: p.label, badge: { id: "state", text: "" }, items: [
50	    { buttons: p.presets.map((q, i) => ({ id: q.id, label: q.label, pressed: i === 0, onClick: () => { stopDemo(); go(q); } })) },
51	    { buttons: [{ id: "car", toggle: [t("Car on the deck"), t("Deck empty")], pressed: loaded, onClick: v => (loaded = v) }] },
52	    { readouts: [{ id: "front", label: t("Front end raised"), unit: t("mm") }, { id: "rear", label: t("Rear end raised"), unit: t("mm") },
53	      { id: "tilt", label: t("Deck tilt"), unit: t("deg") }, { id: "stroke", label: t("Front pistons out"), unit: t("mm") },
54	      { id: "pull", label: t("Front cable pull"), unit: t("kN per side") }, { id: "pF", label: t("Front cylinders"), unit: t("bar to lift") }, { id: "pR", label: t("Rear cylinders"), unit: t("bar to lift") }] },
55	    { buttons: [{ id: "auto", toggle: [t("Demo on"), t("Demo off")], pressed: demo, onClick: v => { demo = v; wait = 0; } }] },
56	    { key: [["--l2", t("deck")], ["--l1", t("cables")], ["--l4", t("cylinders")], ["--metal", t("rods and sheaves")]] },
57	  ] }]);
