63	    const dir = F.clone().sub(R), len = dir.length(), a = Math.atan2(dir.z, dir.x);
64	    deck.position.copy(R).add(F).multiplyScalar(0.5); deck.rotation.set(0, -a, 0); deck.scale.x = len + 0.3;
65	    const t = (m(p.car.x) - ends.rear.x) / (ends.front.x - ends.rear.x), up = V(-Math.sin(a), 0, Math.cos(a));
66	    carBox.visible = loaded; carBox.position.copy(R).addScaledVector(dir, t).addScaledVector(up, 0.025 + ch / 2); carBox.rotation.set(0, -a, 0);
67	    for (const c of units) {
68	      const e = ends[c.name], zDeck = e.z0 + rise[c.name], out = strokeFor(h, rise[c.name]);
69	      const zFixed = zBase - SHEAVE - 0.01, zMoving = zBase + barrel + out + 0.03;
70	      place(c.rod, V(c.x, c.y, zBase + barrel - 0.05), V(c.x, c.y, zMoving));
71	      c.fixed.position.set(c.x, c.y, zFixed); c.moving.position.set(c.x, c.y, zMoving);
72	      // Falls between the blocks (spread across the sheave), then the cable up the post, over the top, down to the deck.
73	      for (let k = 0; k < h.falls; k++) {
