75	        c.falls.setXYZ(2 * k, c.x + dx, c.y, zFixed); c.falls.setXYZ(2 * k + 1, c.x + dx, c.y, zMoving);
76	      }
77	      const n = 2 * h.falls;
78	      c.falls.setXYZ(n, c.x - SHEAVE, c.y, zFixed); c.falls.setXYZ(n + 1, e.x - SHEAVE, c.y, zTop);
79	      c.falls.setXYZ(n + 2, e.x + SHEAVE * 0.2, c.y, zTop + SHEAVE); c.falls.setXYZ(n + 3, e.x + SHEAVE * 0.2, c.y - c.s * 0.07, zDeck);
80	      c.falls.needsUpdate = true;
81	    }
82	    return a;
83	  }
84	
85	  return {
86	    layout({ active }) { group.visible = active; },
87	    update(dt) {
88	      if (demo) { wait += dt; if (wait > 3 && rise.front === target.front && rise.rear === target.rear) { step = (step + 1) % p.presets.length; go(p.presets[step]); wait = 0; } }
89	      // One central pump: the flow is shared by every cylinder that is moving (two per end).
90	      const moving = ["front", "rear"].filter(k => rise[k] !== target[k]), v = deckSpeed({ ...h, flow: h.flow / (2 * Math.max(1, moving.length)) });
91	      for (const k of moving) { const dz = target[k] - rise[k]; rise[k] += Math.sign(dz) * Math.min(Math.abs(dz), v * dt); }
92	      const a = pose();
93	      const pulls = endPulls(m(D.rear[0]), m(D.front[0]), [{ x: (m(D.rear[0]) + m(D.front[0])) / 2, mass: D.mass }, ...(loaded ? [{ x: m(p.car.x), mass: p.car.mass }] : [])]);
94	      ui.set("front", (rise.front * 1000).toFixed(0)); ui.set("rear", (rise.rear * 1000).toFixed(0));
