// Safety models: braking with and without ABS, tipping over and the roll bar, and the crash cases of the safety stops.
import { test } from "node:test";
import assert from "node:assert/strict";
import { mu, peak, simulateStop, createStop } from "../../lib/model/abs.js";
import { tipAngle, tipRate, createRoll, barTime, barAngle } from "../../lib/model/rollover.js";
import { simulateCrash } from "../../lib/model/crash.js";
import { loadCars } from "./helpers.mjs";

const cars = await loadCars();
const params = sub => cars.flatMap(c => c.components.filter(k => k.subsystem === sub).map(k => [c.slug, k.params]));
const wheel = { mass: 400, inertia: 1.2, wheelR: 0.31, torque: 2600, rise: 6 };

test("abs: grip peaks at moderate slip and falls off towards a locked wheel", () => {
  for (const s of ["dry", "wet", "snow"]) {
    assert.ok(peak(s) > mu(s, 1) * 1.2, `${s}: sliding grip well below the peak`);
    assert.ok(mu(s, 0) === 0 && mu(s, 0.1) > mu(s, 0.01));
  }
  assert.ok(peak("dry") > peak("wet") && peak("wet") > peak("snow"));
});

test("abs: without it the wheel locks and slides; with it the stop is shorter and the wheel keeps turning", () => {
  for (const surface of ["dry", "wet"]) {
    const locked = simulateStop({ ...wheel, abs: { on: false } }, surface, 100 / 3.6);
    const abs = simulateStop({ ...wheel, abs: { on: true, release: 0.2, apply: 0.08 } }, surface, 100 / 3.6);
    assert.ok(locked.locked > locked.time * 0.8, `${surface}: locked for most of the stop`);
    assert.equal(abs.locked, 0);
    assert.ok(abs.dist < locked.dist * 0.9, `${surface}: ${abs.dist.toFixed(1)} m vs ${locked.dist.toFixed(1)} m`);
    // Physics floor: no stop can beat the tyre's peak grip.
    assert.ok(abs.dist > (100 / 3.6) ** 2 / (2 * 9.81 * peak(surface)));
  }
  const s = createStop({ ...wheel, abs: { on: false } }, "dry", 20);
  for (let i = 0; i < 60000 && !s.done; i++) s.step(1e-4);
  assert.ok(s.done && s.v === 0);
});

for (const [slug, p] of params("abs")) test(`${slug}: braking stop shortens with ABS on every surface shown`, () => {
  for (const surface of p.surfaces.map(s => s.id)) {
    const off = simulateStop({ ...p.wheel, abs: { on: false } }, surface, p.speed / 3.6), on = simulateStop({ ...p.wheel, abs: { on: true, ...p.abs } }, surface, p.speed / 3.6);
    assert.ok(on.dist < off.dist && on.locked === 0, `${surface}: ${on.dist.toFixed(1)} vs ${off.dist.toFixed(1)}`);
  }
});

test("rollover: the tip angle grows with track and falls with height; below the tip rate the car falls back", () => {
  const car = { halfTrack: 0.76, cgHeight: 0.52, gyration: 0.6 };
  assert.ok(tipAngle(car) > tipAngle({ ...car, cgHeight: 0.8 }));
  const back = createRoll(car, tipRate(car) * 0.95), over = createRoll(car, tipRate(car) * 1.05);
  for (let i = 0; i < 5000; i++) { back.step(1e-3); over.step(1e-3); }
  assert.equal(back.theta, 0); assert.equal(over.theta, Math.PI);
});

test("rollover: the spring bar reaches full travel, faster with a stronger spring", () => {
  const b = { torque: 60, rate: 20, inertia: 0.5, travel: 1.6 };
  const t = barTime(b);
  assert.ok(t > 0 && t < 1);
  assert.ok(barTime({ ...b, torque: 120 }) < t);
  assert.ok(Math.abs(barAngle(b, 5) - b.travel) < 1e-9 && barAngle(b, t / 2) < b.travel);
});

for (const [slug, p] of params("rollover")) test(`${slug}: sensor fires before the tip angle; the device is ready before the car is on its side`, () => {
  assert.ok(p.trigger * Math.PI / 180 < tipAngle(p.car));
  if (p.device === "bar") assert.ok(Math.abs(barTime(p.bar) - p.quoted) < 0.05, `deploys in ${barTime(p.bar).toFixed(3)} s (quoted ${p.quoted} s)`);
  const r = createRoll(p.car, tipRate(p.car) * p.kick);
  let fired = null;
  while (r.theta < Math.PI / 2 && r.t < 5) { r.step(1e-3); if (fired == null && r.theta > p.trigger * Math.PI / 180) fired = r.t; }
  assert.ok(r.theta >= Math.PI / 2, "the demo roll goes over");
  if (p.device === "bar") assert.ok(fired + barTime(p.bar) < r.t, "bar up before the car lies on its side");
});

for (const [slug, p] of params("crumple-zone")) test(`${slug}: the first case keeps the cell whole at every speed shown; the others push it in`, () => {
  const run = (c, kmh) => simulateCrash({ mass: p.mass, v0: kmh / 3.6, zone: c.zone, cellK: c.cellK });
  for (const kmh of [p.speed.min, p.speed.value]) assert.ok(run(p.cases[0], kmh).intrusion < 0.002, `${kmh} km/h`);
  for (const c of p.cases.slice(1)) assert.ok(run(c, p.speed.value).intrusion > 0.002, c.id);
});

// Comfort models: central hydraulics, coach air conditioning, the folding hardtop and torsion-bar levelling.
import { test } from "node:test";
import assert from "node:assert/strict";
import { createSystem, pressureAt, oilAt, force } from "../../lib/model/hydraulics.js";
import { createCabin, steadyTemp } from "../../lib/model/climate.js";
import { roofAt, duration } from "../../lib/model/roof.js";
import { createCorner } from "../../lib/model/air-spring.js";
import { loadCars } from "./helpers.mjs";

const cars = await loadCars();
const params = sub => cars.flatMap(c => c.components.filter(k => k.subsystem === sub).map(k => [c.slug, k.params]));

test("hydraulics: the accumulator's pressure rises with the oil it holds (Boyle) and oilAt inverts it", () => {
  const acc = { gas: 0.002, precharge: 60e5 };
  assert.equal(pressureAt(acc, 0), 60e5);
  assert.ok(Math.abs(pressureAt(acc, oilAt(acc, 150e5)) - 150e5) < 1);
  assert.ok(pressureAt(acc, 0.0012) > pressureAt(acc, 0.0008));
});

for (const [slug, p] of params("comfort-hydraulics")) {
  test(`${slug}: every consumer works from a full accumulator, and the pump refills it`, () => {
    const pmax = p.system.pump.pMax;
    assert.ok(Math.abs(pmax / 1e5 - p.quotedBar) < 1, "cut-out pressure as quoted");
    for (const c of p.consumers) {
      const s = createSystem(p.system);
      assert.ok(force(c, s.pressure()) > c.load * 1.5, `${c.id}: force to spare`);
      s.use(c.id, c, 1);
      let t = 0;
      while (s.moving && t < 30) { s.step(0.002); t += 0.002; }
      assert.ok(s.pos.get(c.id) > 0.999, `${c.id} reaches the end`);
      assert.ok(t > 0.5 && t < 15, `${c.id}: ${t.toFixed(1)} s`);
      assert.ok(s.pressure() < pmax, "the stroke took oil from the accumulator");
      for (let i = 0; i < 60000; i++) s.step(0.002);
      assert.ok(s.pressure() >= p.system.pump.pMin, "pump keeps it charged");
    }
  });
}

for (const [slug, p] of params("cabin-climate")) {
  test(`${slug}: full and in the sun the coach heats far above the outside air; the unit holds it near its setting`, () => {
    const n = p.passengers.max, out = p.outside.value;
    assert.ok(steadyTemp(p.cabin, n, out) > out + 5);
    const s = createCabin(p.cabin, out);
    for (let i = 0; i < 7200; i++) s.step(1, { n: p.passengers.value, outside: out, ac: true });
    assert.ok(Math.abs(s.T - p.cabin.set) < 2, `${s.T.toFixed(1)} °C`);
    assert.ok(s.cooling <= p.cabin.cooling);
  });
}

for (const [slug, p] of params("vario-roof")) {
  test(`${slug}: the roof takes its quoted time and stows inside the boot, under the closed lid`, () => {
    const T = duration(p.roof);
    assert.ok(Math.abs(T - p.quoted) <= 1, `${T} s`);
    const up = roofAt(p.roof, 0), down = roofAt(p.roof, T), b = p.boot;
    assert.equal(up.phase, "up"); assert.equal(down.phase, "down");
    assert.deepEqual(up.A.map(Math.round), p.roof.A);
    for (const [x, z] of [down.A, down.J, down.D]) assert.ok(x > b.x0 && x < b.x1 && z > b.z0 && z < b.z1, `${x.toFixed(0)}, ${z.toFixed(0)}`);
    assert.equal(down.lid, 0);
    const mid = roofAt(p.roof, p.roof.phases[0][1] + p.roof.phases[1][1] + p.roof.phases[2][1] / 2);
    assert.ok(mid.lid > 1, "the lid is open while the roof swings");
  });
}

test("levelling: the torsion bar's motor brings the loaded rear back to ride height; the spring rate, and so the ride, stays soft", () => {
  const corner = kind => createCorner({ kind, k: 30000, emptyMass: 400, damping: 2500, motorRate: 1500 });
  const steel = corner("steel"), bar = corner("torsion");
  for (let i = 0; i < 400000; i++) { steel.step(550, 1e-4); bar.step(550, 1e-4); }
  assert.ok(steel.z > 0.04, `steel sags ${(steel.z * 1000).toFixed(0)} mm`);
  assert.ok(Math.abs(bar.z) < 0.003, `bar levels to ${(bar.z * 1000).toFixed(1)} mm`);
  assert.ok(Math.abs(bar.preload - 150 * 9.81) < 60, "the preload carries the added load");
});

// Open and locked differentials. Pure: no DOM, no three.js. Units: m, s, N, rad/s.

// Cornering: each driven wheel follows its own circle about the turn centre, so the outer wheel turns faster.
// radius = turn radius at the axle centre (m, + = turning left, Infinity = straight), v = axle-centre speed (m/s).
// diff = half the speed difference: the side gears' speed relative to the carrier, which the spider gears take up.
export function cornerSpeeds({ halfTrack, wheelR }, radius, v) {
  const k = Number.isFinite(radius) ? halfTrack / radius : 0;
  const left = v * (1 - k) / wheelR, right = v * (1 + k) / wheelR;
  return { left, right, carrier: (left + right) / 2, diff: (right - left) / 2 };
}

// Drive force on an axle. Open: both sides always get the same torque, so the wheel with less grip limits both.
// Locked: the axle turns as one shaft and each wheel can push up to its own grip.
// p = { torque (N·m at the axle), wheelR, normal (N per wheel), muL, muR, locked, resist (N needed to move the car) }.
export function traction({ torque, wheelR, normal, muL, muR, locked, resist = 0 }) {
  const gripL = muL * normal, gripR = muR * normal, want = torque / wheelR;
  let fL, fR, spinL, spinR;
  if (locked) {
    const grip = gripL + gripR, f = Math.min(want, grip);
    fL = grip ? f * gripL / grip : 0; fR = f - fL;
    spinL = spinR = want > grip;
  } else {
    // The wheel with less grip spins first; that caps the torque on both sides, so the other wheel never spins.
    const each = Math.min(want / 2, gripL, gripR);
    fL = fR = each;
    spinL = want / 2 > gripL && gripL <= gripR; spinR = want / 2 > gripR && gripR <= gripL;
  }
  const total = fL + fR;
  return { fL, fR, total, spinL, spinR, moves: total > resist };
}

// Four-wheel drive through three differentials: front, centre and rear, each open or locked. With traction control by the
// brakes (4ETS, brake > 0) a wheel that would spin on an open differential is braked instead, so its side of the
// differential can pass on up to `brake` more. Forces at the tyres in N, wheels ordered fl, fr, rl, rr.
// p = { force (N: the engine's drive at the wheels, all four together), normal (N per wheel), mu: [4], front, centre,
//   rear (true = locked), brake (N a wheel brake can hold back, 0 = none), resist (N needed to move the car) }.
export function traction4({ force, normal, mu, front, centre, rear, brake = 0, resist = 0 }) {
  const grip = mu.map(m => m * normal);
  // One axle: input = the force put into its differential; drive = what its tyres push. Open, each side takes input/2,
  // which may be up to its grip plus what its brake can hold; locked, the sides share it in proportion to grip.
  const axle = (gL, gR, locked) => ({
    max: locked ? gL + gR : 2 * Math.min(gL, gR) + 2 * brake,
    drive: input => (locked ? Math.min(input, gL + gR) : Math.min(input / 2, gL) + Math.min(input / 2, gR)),
    locked, g: [gL, gR],
  });
  const axles = [axle(grip[0], grip[1], front), axle(grip[2], grip[3], rear)];
  let inputs;
  if (!centre) { const i = Math.min(force / 2, axles[0].max, axles[1].max); inputs = [i, i]; }
  else {
    // Locked centre: split the input where it drives most (brakes waste whatever they hold back).
    let best = -1;
    for (let k = 0; k <= 200; k++) {
      const f = Math.min(force, axles[0].max) * k / 200, r = Math.min(force - f, axles[1].max);
      const d = axles[0].drive(f) + axles[1].drive(r);
      if (d > best + 1e-9) { best = d; inputs = [f, r]; }
    }
  }
  const drive = axles[0].drive(inputs[0]) + axles[1].drive(inputs[1]);
  const excess = force > inputs[0] + inputs[1] + 1e-6;
  // Which wheels spin: with drive left over, those of an axle that takes all it can and whose own grip (plus brake) is
  // used up. Which are braked: on an open axle, those given more than their grip.
  const spin = [], braked = [];
  axles.forEach((a, k) => a.g.forEach(g => {
    const full = inputs[k] >= a.max - 1e-6, side = inputs[k] / 2;
    spin.push(excess && full && (a.locked || side >= g + brake - 1e-6));
    braked.push(!a.locked && brake > 0 && side > g + 1e-6 ? Math.min(brake, side - g) : 0);
  }));
  return { drive, moves: drive > resist, spin, braked, inputs };
}

// Portal axle (Unimog) against a conventional beam axle. Pure: no DOM, no three.js. Units: m, N·m.
// On a portal axle the half-shafts run above the wheel centres and drive each hub through a pair of spur gears (the
// portal), so the axle tube and differential sit higher by the gears' drop. The gears also reduce: the shafts turn
// `ratio` times faster than the wheels and carry 1/ratio of the wheel torque.
// a = { wheelR, tubeR (radius of the axle tube), diffR (lowest point of the differential housing below the axle centre),
//   drop (m: hub centre to half-shaft centre, 0 = conventional), ratio (hub reduction, 1 = none) }.
export const axleHeight = a => a.wheelR + a.drop;
export const clearance = a => axleHeight(a) - a.diffR;                // under the differential, the lowest point
export const clearsRock = (a, h) => clearance(a) > h;
export const shaftTorque = (a, wheelTorque) => wheelTorque / a.ratio;
export const shaftSpeed = (a, wheelSpeed) => wheelSpeed * a.ratio;

