  group.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints([V(bx[0], w / 2, bz[0]), V(bx[1], w / 2, bz[0]), V(bx[1], w / 2, bz[1]), V(bx[0], w / 2, bz[1])]), bootMat));

