  return {
    layout({ active, onPhoto: photo }) { group.visible = active; onPhoto = photo; wall.visible = !photo; tyreMat.opacity = photo ? 0.12 : 1; pose(); },
    update(dt) {
      if (playing) { clock += dt; if (clock > APPROACH + sims[kase].duration * p.slow + HOLD) clock = 0; }
      pose();
    },
  };
}

