    { buttons: [{ id: "auto", toggle: [t("Auto demo on"), t("Auto demo off")], pressed: auto, onClick: v => (auto = v) }] },
    { key: [["--l4", t("air bellows")], ["--metal", t("steel coil spring")], ["--accent", t("passengers")], ["--l2", t("luggage")]] },
