content.content:
// node ghost.mjs <slug> <out.png> [crop…]: project a car's body.ghost through its photo.cam onto the photo.
import { writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
const [slug, out, ...crop] = process.argv.slice(2);
const car = (await import(pathToFileURL(resolve(`stops/${slug}/car.js`)))).default;
const shapes = [], cols = ["#f0f", "#0f0", "#ff0", "#0ff", "#f80"];
car.body.ghost.forEach((g, i) => {
  const color = cols[i % cols.length];
  if (g.pts) for (const y of g.y) shapes.push({ y, pts: g.pts, closed: true, color });
  if (g.torus) {
    const { R, r, pos } = g.torus, ys = g.mirror ? [pos[1], -pos[1]] : [pos[1]];
    for (const y of ys) for (const rr of [R + r, R - r]) shapes.push({ y, closed: true, color, pts: Array.from({ length: 48 }, (_, k) => [pos[0] + rr * Math.cos(k * Math.PI / 24), pos[2] + rr * Math.sin(k * Math.PI / 24)]) });
  }
});
const ov = `${out}.json`;
writeFileSync(ov, JSON.stringify({ cam: car.photo.cam, image: { width: car.photo.w, height: car.photo.h }, shapes }));
console.log(execFileSync("node", ["tools/photo-grid.mjs", `stops/${slug}/${car.photo.src}`, out, ...(crop.length ? crop : [0, 0, car.photo.w, car.photo.h, 1, 100]), "--overlay", ov]).toString().trim());

