// seeds?, focalPrior?, frame? } → tools/photo-fits/<slug>.json (wheel X from the car's ghost tori) and the fit's output.
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
const [slug, specPath] = process.argv.slice(2), spec = JSON.parse(readFileSync(specPath, "utf8"));
const car = (await import(pathToFileURL(resolve(`stops/${slug}/car.js`)))).default;
const tori = car.body.ghost.filter(g => g.torus).map(g => g.torus.pos);
const img = execFileSync("sips", ["-g", "pixelWidth", "-g", "pixelHeight", spec.photo]).toString().match(/\d+$/gm).map(Number);
const points = [];
for (const [k, [hub, bot, wh = 3, wb = 2]] of Object.entries(spec.points)) {
  const [x, y, z] = tori[+k[0]], s = k[1] === "L" ? 1 : -1, n = `${["front", "second", "third"][+k[0]]} ${k[1] === "L" ? "left" : "right"}`;
  if (hub) points.push({ name: `${n} hub`, X: [x, s * y, z], px: hub, w: wh });
  if (bot) points.push({ name: `${n} tyre bottom`, X: [x, s * y, 0], px: bot, w: wb });
}
points.push(...(spec.extra ?? []));
const xs = tori.map(p => p[0]), mid = (Math.min(...xs) + Math.max(...xs)) / 2, R = spec.dist ?? 6000;
const seeds = spec.seeds ?? [0, 1, 2, 3, 4, 5, 6, 7].map(i => [mid + R * Math.cos(i * Math.PI / 4), R * Math.sin(i * Math.PI / 4), 1500]);
const fit = { photo: `stops/${slug}/photo.jpg`, image: { width: img[0], height: img[1] },
  frame: spec.frame ?? "mm; x forward, y left, z up; origin = front axle centre on the ground. Wheel centres and radii from the car's ghost (car.js)",
  aimAt: [mid, 0, 600], seeds, focalSeeds: spec.focalSeeds ?? [700, 1000, 1400], rollPenalty: 200, focalPrior: spec.focalPrior ?? { f: 1000, w: 0.05 }, groundZ: 0, points };
writeFileSync(`tools/photo-fits/${slug}.json`, JSON.stringify(fit, null, 2) + "\n");
console.log(execFileSync("node", ["tools/fit-photo-camera.mjs", `tools/photo-fits/${slug}.json`]).toString().trim());
EOF
