# python3 -I exif.py <jpg>...: print FocalLength and FocalLengthIn35mmFilm from the EXIF block (plain parser, no libraries).
import sys, struct
def tags(b):
    i = 2
    while i < len(b) - 4:
        if b[i] != 0xFF: return {}
        m, n = b[i + 1], struct.unpack(">H", b[i + 2:i + 4])[0]
        if m == 0xE1 and b[i + 4:i + 10] == b"Exif\0\0": return tiff(b[i + 10:i + 2 + n])
        i += 2 + n
    return {}
def tiff(t):
    e = "<" if t[:2] == b"II" else ">"; out = {}
    def ifd(o):
        if o + 2 > len(t): return
        for k in range(struct.unpack(e + "H", t[o:o + 2])[0]):
            p = o + 2 + 12 * k; tag, typ, cnt = struct.unpack(e + "HHI", t[p:p + 8]); v = t[p + 8:p + 12]
            if tag == 0x8769: ifd(struct.unpack(e + "I", v)[0])
            elif tag == 0x920A and typ == 5: q = struct.unpack(e + "I", v)[0]; a, d = struct.unpack(e + "II", t[q:q + 8]); out["FL"] = a / d
            elif tag == 0xA405: out["FL35"] = struct.unpack(e + "H", v[:2])[0]
            elif tag == 0x0110: q = struct.unpack(e + "I", v)[0] if cnt > 4 else p + 8; out["model"] = t[q:q + cnt].rstrip(b"\0").decode("latin1")
    ifd(struct.unpack(e + "I", t[4:8])[0]); return out
