// node addphoto.mjs <urls.json> <alts.json> <slug>...: run each fit, then write photo{} into car.js and its alt into hu.js.
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
const [urlsP, altsP, ...slugs] = process.argv.slice(2), urls = JSON.parse(readFileSync(urlsP, "utf8")), alts = JSON.parse(readFileSync(altsP, "utf8"));
const q = s => JSON.stringify(s);
for (const slug of slugs) {
  const out = execFileSync("node", ["tools/fit-photo-camera.mjs", `tools/photo-fits/${slug}.json`]).toString(), cam = out.split("\n")[0].replace(/^cam: /, "").replace(/,\s*$/, "");
  const fit = JSON.parse(readFileSync(`tools/photo-fits/${slug}.json`, "utf8")), u = urls[slug], author = u.author.replace(/\s*\(Website\)$/, "");
  const block = `  photo: {\n    src: "photo.jpg", w: ${fit.image.width}, h: ${fit.image.height},\n    alt: ${q(alts[slug][0])},\n    cam: ${cam}, // tools/photo-fits/${slug}.json\n` +
    `    credit: { author: ${q(author)}, license: ${q(u.license)}, url: ${q(u.url)} },\n  },\n`;
  let car = readFileSync(`stops/${slug}/car.js`, "utf8");
  if (car.includes("\n  photo: {")) throw new Error(`${slug} already has a photo`);
  car = car.replace(/^\/\/ Photo to fit \(not yet downloaded\):.*\n/m, "").replace("\n  components: [", `\n${block}  components: [`);
  writeFileSync(`stops/${slug}/car.js`, car);
  let hu = readFileSync(`stops/${slug}/hu.js`, "utf8");
  hu = hu.replace("\n  components: [", `\n  photo: { alt: ${q(alts[slug][1])} },\n  components: [`);
  writeFileSync(`stops/${slug}/hu.js`, hu);
  console.log(slug, out.trim().split("\n").pop());
}
EOF
